/// before each Engram layer, whose rows the host reads between the stretches): a stretch is captured the first time
/// its (rows, bucket, stretch) comes up and replayed after, with what it leaves. The same launches with the same
/// arguments as the eager round, so the same bytes. At most `cap` stretches are kept (TF_DS_GRAPH_CAP, rank 1's
/// --graph-cap; 0: all): past it the least recently replayed one is destroyed and captured again when it next comes
/// up. Uncapped, the keys (rows x buckets x stretches x shard modes) add up over days of growing conversations, each
/// graph holding device and host memory until the process ends. Both ranks see the same keys in the same order, so
/// with the same cap they keep and drop the same stretches.
pub const Graphs = struct {
    gpa: std.mem.Allocator,
    lru: graph_cache.Lru(Key, Entry),

    // mode: the round's shard.Mode (auto's choice); map: TF_DS_GREEDY_ARGMAX's head (the exchange, not the logits' gather)
    // topk: TF_DS_TOPK_MERGE's kmax on the stretch that runs the head (the select's argument and the exchange's size;
    // 0 elsewhere, whose launches it does not change)
    pub const Key = struct { rows: u32, bucket: u64, stretch: u32, mode: u8 = 0, map: u8 = 0, topk: u8 = 0 };
    const Entry = struct { exec: cuda.graph.Exec, start: Carry, end: Carry };

    pub fn init(gpa: std.mem.Allocator, cap: usize) Graphs {
        return .{ .gpa = gpa, .lru = .init(cap) };
    }

    pub fn deinit(g: *Graphs) void {
        var it = g.lru.valueIterator();
        while (it.next()) |en| en.exec.deinit();
        g.lru.deinit(g.gpa);
        g.* = undefined;
    }

    /// The captured stretches.
    pub fn count(g: *const Graphs) usize {
        return g.lru.count();
    }

    fn run(g: *Graphs, key: Key, e: *const Engine, rd: *Round, ch: *const Chunk, cs: *const Caches, rings: []const u64, cy: *Carry, li: usize, end: usize) !void {
        if (g.lru.get(key)) |en| {
            if (!std.meta.eql(en.start, cy.*)) return error.GraphStateMismatch;
            try en.exec.launchOn(e.s);
            cy.* = en.end;
            rd.kk = cy.kk;
            rd.has_cand = cy.has_cand;
            rd.has_cblk = cy.has_cblk;
            return;
        }
        const start = cy.*;
        try cuda.graph.beginCapture(e.s, .thread_local);
        stretch(e, rd, ch, cs, rings, cy, li, end, null) catch |err| {
            if (cuda.graph.endCapture(e.s)) |got| {
                var x = got;
                x.deinit();
            } else |_| {}
            return err;
        };
        var graph = try cuda.graph.endCapture(e.s);
        defer graph.deinit();
        var exec = try graph.instantiate();
        errdefer exec.deinit();
        // launched before it is kept: a failed launch frees it here and leaves no handle in the cache; a graph still
        // running when destroyed (this one if the put fails, or an evicted one) is freed when it completes
        try exec.launchOn(e.s);
        if (try g.lru.put(g.gpa, key, .{ .exec = exec, .start = start, .end = cy.* })) |old| {
            var x = old.exec;
            x.deinit();
            if (std.math.isPowerOfTwo(g.lru.evicted)) std.log.info("dsv41: CUDA graphs: {d} kept (the cap), {d} destroyed for newer ones so far; a count that keeps rising means TF_DS_GRAPH_CAP is below the working set", .{ g.lru.count(), g.lru.evicted });
        } else if (std.math.isPowerOfTwo(g.lru.count()) and g.lru.count() >= 64) std.log.info("dsv41: CUDA graphs: {d} kept", .{g.lru.count()});
    }
};

/// A round's errors after which the ranks cannot go on together: the ring or the communicator dead (RingFailed,
/// CommAborted), a decode round's ring transfers out of their fixed order or row lists (RingOrder, ShardRingOrder,
/// BadRingRows: a sized send may be in flight with no receive, or the peer waits in a collect), a prompt chunk's Engram
/// rows that one rank could not read (EngramRankFault: the peer waits in the layer's allGather). Rank 0 ends the pair
/// on each (native.pair_fatal: TF_DS_PAIR_BROKEN=exit exits 75, both ranks restart); a follower stops following
/// (lanes.followPair) instead of taking the next frame.
pub const pair_ending = [_]anyerror{ error.RingFailed, error.CommAborted, error.RingOrder, error.ShardRingOrder, error.BadRingRows, error.EngramRankFault };

pub fn endsPair(err: anyerror) bool {
    for (pair_ending) |x| if (x == err) return true;
    return false;
}

/// A round of these rows through every layer and the head: rd.logits [R, vocab] and rd.taps. The caches (ring, the
/// compressed rows, the positional store) are the prompt's, extended by the rows; eh: the Engram host (the rows' n-grams
/// hashed from `seq`, the whole sequence's ids through the rows'). With `graphs` each stretch runs as its graph and a
/// probe sees only the round's end (its logits and taps).
pub fn forward(e: *const Engine, rd: *Round, ch: *const Chunk, cs: *const Caches, rings: []const u64, eh: ?*prompt.EngramHost, seq: []const i32, rows: Rows, pool_cap: usize, probe: ?Probe, graphs: ?*Graphs) !void {
    const w = e.w;
    const R = rows.ids.len;
    if (R == 0 or R > e.round_rows or rows.pos.len != R) return error.BadRound;
    rd.r = R;
    // kernels.round_rows(): up to the round's bound its rows take the row-invariant decode kernels
    const bound = tri.decode_rows;
    tri.decode_rows = e.round_rows;
    defer tri.decode_rows = bound;
    var deepest: usize = 0;
    for (rows.pos) |p| deepest = @max(deepest, @as(usize, @intCast(p)) + 1);
    // TF_DS_IDX_BUCKET_FINER: the context's own size rounded up, not its next power of two (see the switch's note)
    rd.bucket = if (rd.finer) bucketFiner(deepest, pool_cap, bucket_gran) else bucketFor(deepest, pool_cap);
    rd.has_cand = false;
    rd.has_cblk = false;
    rd.kk = 0;
    try setGlue(e, rd, rows);
    rd.smode = .off;
    rd.sring = false;
    // a round that fails part way leaves the layer cursor and the early-q flag clean for the next (a ring send still
    // awaiting its receive is left open on purpose: every later ring transfer refuses, RingOrder, and the round's
    // error ends the pair, native.pair_fatal)
    errdefer {
        rd.rcur.reset();
        rd.ss_q_out = false;
    }
    if (e.kv) |kv| try shardRound(e, rd, rows, kv);
    var cy: Carry = .{ .h = rd.h, .spare = rd.h_alt, .pre = rd.pre, .pre_f = rd.pre_f };
    // the round's Engram reads, every layer's at once (AIO): hashed and submitted once the first stretch is issued
    // (its GPU time covers the reads), landed on the host before each Engram layer's stretch (both layers at the
    // first with TF_DS_ENGRAM_BOTH)
    var ah: Ahead = .{};
    var ahead = e.c.engram_layers.slice().len == 0;
    // TF_DS_ENGRAM_SUBMIT_EARLY: the rows hashed at the drafter pass's return (rd.esh) cover every window: flatten
    // and submit them now, before stretch 0 (the hashing sat after its issue, on the round's critical path); a stash
    // that covers no window takes the inline path below, today's
    if (!ahead) if (eh) |x| {
        ahead = try engramStashed(e, x, rows, &rd.esh, &ah);
    };
    // the stretches: cut before each Engram layer, its rows read on the host before it (TF_DS_ENGRAM_BOTH: one cut,
    // before the first Engram layer, for both layers' rows)
    var li: usize = 0;
    var sn: u32 = 0;
    try rd.clock(e, Round.clock_start);
    rd.launch_mark = cuda.launch.count;
    while (li < w.layers.len) : (sn += 1) {
        var end = li + 1;
        if (rd.engram_both and li == e.c.engram_layers.slice()[0]) {
            // TF_DS_ENGRAM_BOTH: both Engram layers' rows landed at the first cut; this stretch runs the rest of the
            // round, the head included, in one go
            end = w.layers.len;
        } else {
            while (end < w.layers.len and w.layers[end].engram_wkv == null) end += 1;
        }
        if (w.layers[li].engram_wkv != null) {
            if (!ahead) try engramAhead(e, eh orelse return error.NoEngramTables, seq, rows, &ah);
            ahead = true;
            if (!(rd.engram_both and ah.both)) try engramLand(e, rd, eh orelse return error.NoEngramTables, &ah, li);
        }
        try rd.clock(e, Round.clock_wait);
        if (graphs) |g| {
            try g.run(.{ .rows = @intCast(R), .bucket = rd.bucket, .stretch = sn, .mode = @intFromEnum(rd.smode), .map = @intFromBool(rd.map), .topk = if (end == w.layers.len) rd.topk else 0 }, e, rd, ch, cs, rings, &cy, li, end);
        } else try stretch(e, rd, ch, cs, rings, &cy, li, end, probe);
        try rd.clock(e, Round.clock_tail);
        if (!ahead) try engramAhead(e, eh orelse return error.NoEngramTables, seq, rows, &ah);
        ahead = true;
        li = end;
    }
    if (graphs != null) {
        try Probe.check(probe, .logits, w.layers.len, rd.logits);
        if (cy.ntap > 0) try Probe.check(probe, .taps, w.layers.len, rd.taps);
    }
}

