/// TF_DS_ENGRAM_SUBMIT_EARLY (off by default): a drafter pass's return hashes its streams' next window rows (each
/// one's pending row and the drafts it holds - the superset the round's window trims) into this per-round stash,
/// keyed by pool slot, so a round's hashing and submit leave its critical path (they sat after stretch 0's issue).
/// The round's start covers each window from its entry (covers: its rows a prefix of the stashed superset, the ids
/// identical) and submits the reads there; a window the stash does not cover takes the inline engramAhead as ever.
/// The stash is its own buffer: engramAhead and the prompt fallback still own eh.hashes between them.
pub const EngramStash = struct {
    /// The widest window's rows (lanes.window_rows: the pending row and the drafter's block; roundWins refuses wider):
    /// the stash hashes at most these many, and no window reads past them.
    pub const rows_max = 8;

    pub const Entry = struct {
        valid: bool = false,
        slot: usize = 0,
        start: usize = 0, // the pending row's position in its stream's sequence
        n: usize = 0, // the stashed rows: the pending row and the held drafts, [0, rows_max]
        pre_len: usize = 0,
        pre: [engram.max_ngram - 1]i32 = @splat(0), // the ids before `start` the rows' n-grams reach back to
        ids: [rows_max]i32 = @splat(0), // the stashed rows' ids (pending + held)
        hashes: [rows_max * engram.max_layers * engram.max_cols]i64 = @splat(0), // [n][layers][cols], Hasher.hashes' layout

