        /// a pure function of exactly these ids). A window's host rows past the superset, a start that moved, or a
        /// released slot's dropped entry: not covered - the round then hashes its rows as before.
        pub fn covers(en: Entry, slot: usize, start: usize, pre: []const i32, ids: []const i32) bool {
            return en.valid and en.slot == slot and en.start == start and en.pre_len == pre.len and
                std.mem.eql(i32, en.pre[0..pre.len], pre) and ids.len <= en.n and std.mem.eql(i32, en.ids[0..ids.len], ids);
