/// The served engine's window width (dsv41's window_rows: six rows), so a score stream's forced windows are five
/// recorded ids and the round's pending row.
fn scoreModel() !Config {
    var costs: [6]@import("config.zig").Cost = undefined;
    for (&costs, 1..) |*c, w| c.* = .{ .width = @intCast(w), .ms = 5.0 + 0.8 * @as(f64, @floatFromInt(w)) };
    return Config.init(gpa, .{ .exact_width = 6, .gpu_tokens = true, .mtp = true, .speculate = true, .speculate_early = false, .drafts = 4, .window_costs = &costs, .mtp_step_ms = 0.5, .hidden_rows = true, .batch_rows = 32, .max_streams = 8, .draft_streams = true }, 16, 15);
}

const ScoreRun = struct { emitted: []u32, windows: []usize };

/// One score stream alone on the fake target, its windows' rows in order; eos empty as the server sends a score
/// request (every recorded token is fed, none ends the scoring).
fn runScore(prompt: []const u32, ids: []const u32) !ScoreRun {
    var cfg = try scoreModel();
    defer cfg.deinit(gpa);
    var target: fake.Fake = .{ .gpa = gpa };
    defer target.deinit();
    var clock: fake.FixedClock = .{};
    var engine = Engine.init(gpa, &cfg, target.backend(), clock.clock());
    defer engine.deinit();
    var s = try sm.Stream.init(gpa, .{ .id = "score", .prompt = prompt, .max_new = @intCast(ids.len), .eos = &.{}, .drafts = false, .score = ids });
    defer s.deinit(gpa);
    try engine.addStream(&s);
    while (engine.activeCount() > 0) try engine.step();
    return .{ .emitted = try gpa.dupe(u32, s.emitted()), .windows = try gpa.dupe(usize, target.windows.items) };
}

fn freeScore(r: ScoreRun) void {
    gpa.free(r.emitted);
    gpa.free(r.windows);
}

