test "a failed stretch joins what it forked, ends its capture, and owes the next capture no join" {
    const Fake = struct {
        const Call = enum { side, prefetch, compress, shardq, end, free, forget };
        calls: [7]Call = undefined,
        n: usize = 0,
        side_fails: bool = false,
        prefetch_fails: bool = false,
        compress_fails: bool = false,
        shardq_fails: bool = false,
        end_fails: bool = false,

        const Self = @This();
        const Graph = struct {
            f: *Self,
            fn deinit(g: *Graph) void {
                g.f.note(.free);
            }
        };

        fn note(f: *Self, c: Call) void {
            f.calls[f.n] = c;
            f.n += 1;
        }
        fn joinSide(f: *Self) !void {
            f.note(.side);
            if (f.side_fails) return error.CudaFailed;
        }
        fn joinPrefetch(f: *Self) !void {
            f.note(.prefetch);
            if (f.prefetch_fails) return error.CudaFailed;
        }
        fn joinCompress(f: *Self) !void {
            f.note(.compress);
            if (f.compress_fails) return error.CudaFailed;
        }
        fn joinShardQ(f: *Self) !void {
            f.note(.shardq);
            if (f.shardq_fails) return error.CudaFailed;
        }
        fn end(f: *Self) !Graph {
            f.note(.end);
            if (f.end_fails) return error.CudaFailed;
            return .{ .f = f };
        }
        fn forgetForked(f: *Self) void {
            f.note(.forget);
        }
    };
    // every join before the end, the graph it returns freed, the flags cleared last
    const whole = [_]Fake.Call{ .side, .prefetch, .compress, .shardq, .end, .free, .forget };
    var ok: Fake = .{};
    leaveCapture(&ok);
    try std.testing.expectEqualSlices(Fake.Call, &whole, ok.calls[0..ok.n]);
    // a failed join stops nothing after it
    var side: Fake = .{ .side_fails = true };
    leaveCapture(&side);
    try std.testing.expectEqualSlices(Fake.Call, &whole, side.calls[0..side.n]);
    var prefetch: Fake = .{ .prefetch_fails = true };
    leaveCapture(&prefetch);
    try std.testing.expectEqualSlices(Fake.Call, &whole, prefetch.calls[0..prefetch.n]);
    var compress: Fake = .{ .compress_fails = true };
    leaveCapture(&compress);
    try std.testing.expectEqualSlices(Fake.Call, &whole, compress.calls[0..compress.n]);
    var shardq: Fake = .{ .shardq_fails = true };
    leaveCapture(&shardq);
    try std.testing.expectEqualSlices(Fake.Call, &whole, shardq.calls[0..shardq.n]);
    // an invalidated capture's refused joins and end still clear the flags
    var dead: Fake = .{ .side_fails = true, .prefetch_fails = true, .compress_fails = true, .shardq_fails = true, .end_fails = true };
    leaveCapture(&dead);
    try std.testing.expectEqualSlices(Fake.Call, &.{ .side, .prefetch, .compress, .shardq, .end, .forget }, dead.calls[0..dead.n]);
    // the real one clears every fork flag
    var rd: Round = undefined;
    rd.side_out = true;
    rd.pf_out = true;
    rd.cs_out = true;
    rd.ss_q_out = true;
    (StretchCapture{ .e = undefined, .rd = &rd }).forgetForked();
    try std.testing.expect(!rd.side_out);
    try std.testing.expect(!rd.pf_out);
    try std.testing.expect(!rd.cs_out);
    try std.testing.expect(!rd.ss_q_out);
}

